sys_script.script:
(function executeRule(current, previous) {
    // Only act when a customer_order is linked
    var coSysId = current.getValue('customer_order');
    if (!coSysId) {
        return;
    }

    // On insert: only propagate if fulfillment_location is empty
    // On update: only propagate if customer_order just changed
    var isInsert = current.operation() == 'insert';
    var coChanged = previous && current.customer_order.changes();

    if (isInsert) {
        var existingLoc = current.getValue('fulfillment_location');
        if (existingLoc) {
            return; // Respect explicit value
        }
    } else {
        if (!coChanged) {
            return;
        }
    }

    // Use WarehouseRouter to resolve and validate the warehouse
    var router = new x_2056099_indust_0.WarehouseRouter();
    var result = router.resolveFromOrder(coSysId);

    if (result.success) {
        // Set fulfillment_location — the customer's delivery warehouse.
        // Do NOT set production_location — that represents where
        // production machines are, which is determined by
        // assigned_resource / resource allocation, not by the
        // customer's warehouse choice.
        current.setValue('fulfillment_location', result.warehouse.sys_id);
        gs.info(
            'WarehouseRouter: Set fulfillment_location to "' +
            result.warehouse.location_name + '" (' +
            result.warehouse.location_id + ') on Production Order ' +
            (current.getValue('number') || '(new)') +
            ' from Customer Order ' + result.order_number
        );
    } else {
        gs.warn(
            'WarehouseRouter: Could not resolve fulfillment warehouse ' +
            'for Production Order from Customer Order ' + coSysId +
            ': ' + result.error
        );
    }
})(current, previous);
